export interface EventKnowledge {
  topic: string;
  term: string;
  definition: string;
  mechanism: string;
  application: string;
}

function k(topic: string, term: string, definition: string, mechanism: string, application: string): EventKnowledge {
  return { topic, term, definition, mechanism, application };
}

